function sendFileToWebView() {
  const payload = {
    FileDoc: "",
    FileName: "ASI_RESEARCH 1.pdf",
    FileContent: "application/pdf",
  };
  // iOS: native side registers messageHandlers.downloadHandler via WKUserContentController
  if (window.webkit?.messageHandlers?.downloadHandler) {
    window.webkit.messageHandlers.downloadHandler.postMessage(payload);
    return;
  }

  // Android: native side registers this via webView.addJavascriptInterface(obj, "Android")
  // JavascriptInterface methods only accept primitives, so the payload is JSON-stringified.
  if (window.Android?.postMessage) {
    window.Android.postMessage(JSON.stringify(payload));
    return;
  }

  alert("No native download bridge available (not running inside the iOS or Android WebView host)");
}

function getDeviceType() {
  const userAgent = navigator.userAgent || navigator.vendor || window.opera;

  // Check for "iPhone" or "iPod" in the user agent string
  if (/iPhone|iPod/.test(userAgent) && !window.MSStream) {
    return "iPhone";
  }

  // Check for "iPad" in the user agent string (older iPadOS)
  if (/iPad/.test(userAgent) && !window.MSStream) {
    return "iPad";
  }

  // Modern iPadOS detection (User Agent contains "Macintosh" and is touch-enabled)
  if (
    /Macintosh/.test(userAgent) &&
    ("ontouchstart" in window || navigator.maxTouchPoints > 0)
  ) {
    return "iPad";
  }

  // Check for Android devices
  if (/Android/.test(userAgent)) {
    // Further check if it's an Android tablet (no "Mobile" keyword)
    if (!/mobile/i.test(userAgent)) {
      return "Android Tablet";
    }
    return "Android Phone";
  }

  // Other platforms
  if (/Windows Phone/.test(userAgent)) {
    return "Windows Phone";
  }

  return "unknown";
}

function getBrowserInfo() {
  const ua = navigator.userAgent;
  let browser = "Unknown";
  let version = "";

  if (ua.includes("Firefox")) {
    browser = "Firefox";
    version = ua.match(/Firefox\/([\d.]+)/)[1];
  } else if (ua.includes("Edg")) {
    browser = "Microsoft Edge";
    version = ua.match(/Edg\/([\d.]+)/)[1];
  } else if (ua.includes("Chrome")) {
    browser = "Chrome";
    version = ua.match(/Chrome\/([\d.]+)/)[1];
  } else if (ua.includes("Safari")) {
    browser = "Safari";
    version = ua.match(/Version\/([\d.]+)/)?.[1] || "";
  }

  return `${browser} ${version}`;
}

function detectOS() {
  const platform = navigator.platform.toLowerCase();
  if (platform.includes("win")) return "Windows";
  if (platform.includes("mac")) return "macOS";
  if (platform.includes("linux")) return "Linux";
  if (/iphone|ipad|ipod/.test(navigator.userAgent.toLowerCase())) return "iOS";
  if (/android/.test(navigator.userAgent.toLowerCase())) return "Android";
  return "Unknown";
}

function isWebGLSupported() {
  try {
    const canvas = document.createElement("canvas");
    return !!(
      window.WebGLRenderingContext &&
      (canvas.getContext("webgl") || canvas.getContext("experimental-webgl"))
    );
  } catch (e) {
    return false;
  }
}

function addRow(label, value) {
  const grid = document.getElementById("infoGrid");

  const col = document.createElement("div");
  col.className = "col-12 col-sm-6 col-lg-4";

  const item = document.createElement("div");
  item.className = "info-item h-100 p-3 rounded-3 border bg-light-subtle";

  const labelEl = document.createElement("div");
  labelEl.className = "text-muted small text-uppercase fw-semibold mb-1";
  labelEl.textContent = label;

  const valueEl = document.createElement("div");
  valueEl.className = "fw-semibold text-break mb-0";

  if (typeof value === "boolean") {
    const badge = document.createElement("span");
    badge.className = `badge rounded-pill ${value ? "text-bg-success" : "text-bg-secondary"}`;
    badge.textContent = value ? "Yes" : "No";
    valueEl.appendChild(badge);
  } else {
    valueEl.textContent = value;
  }

  item.appendChild(labelEl);
  item.appendChild(valueEl);
  col.appendChild(item);
  grid.appendChild(col);
}

function loadInfo() {
  addRow("User Agent", navigator.userAgent);
  addRow("Device Type", getDeviceType());
  addRow("Browser", getBrowserInfo());
  addRow("Operating System", detectOS());
  addRow("Platform", navigator.platform);
  addRow("Language", navigator.language);
  addRow("Cookies Enabled", navigator.cookieEnabled);
  addRow("Online Status", navigator.onLine);
  addRow("Java Enabled", navigator.javaEnabled());
  addRow("Touch Support", "ontouchstart" in window);
  addRow("WebGL Supported", isWebGLSupported());
  addRow("LocalStorage Supported", typeof Storage !== "undefined");
  addRow(
    "Dark Mode Preferred",
    window.matchMedia("(prefers-color-scheme: dark)").matches,
  );

  addRow("Screen Resolution", `${screen.width} x ${screen.height}`);
  addRow("Viewport Size", `${window.innerWidth} x ${window.innerHeight}`);
}

function handleCarChange(event) {
  alert(`Selected: ${event.target.value}`);
}

loadInfo();

window.addEventListener("resize", () => {
  location.reload();
});
